CREATE TABLE app_users (id BIGINT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL);
CREATE TABLE venues (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,address VARCHAR(255) NOT NULL,latitude DOUBLE PRECISION NOT NULL,longitude DOUBLE PRECISION NOT NULL);
CREATE TABLE seats (id BIGINT AUTO_INCREMENT PRIMARY KEY,venue_id BIGINT NOT NULL,label VARCHAR(40) NOT NULL,tier VARCHAR(20) NOT NULL,CONSTRAINT uq_venue_label UNIQUE(venue_id,label),FOREIGN KEY(venue_id) REFERENCES venues(id));
CREATE TABLE sponsors (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL);
CREATE TABLE events (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,venue_id BIGINT NOT NULL,starts_at TIMESTAMP(6) NOT NULL,early_bird_until TIMESTAMP(6) NOT NULL,base_price DECIMAL(19,2) NOT NULL,currency VARCHAR(3) NOT NULL,published BOOLEAN NOT NULL,FOREIGN KEY(venue_id) REFERENCES venues(id));
CREATE TABLE event_sponsors (event_id BIGINT NOT NULL,sponsor_id BIGINT NOT NULL,PRIMARY KEY(event_id,sponsor_id),FOREIGN KEY(event_id) REFERENCES events(id),FOREIGN KEY(sponsor_id) REFERENCES sponsors(id));
CREATE TABLE bookings (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,event_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL,expires_at TIMESTAMP(6) NOT NULL,created_at TIMESTAMP(6) NOT NULL,total DECIMAL(19,2) NOT NULL,currency VARCHAR(3) NOT NULL,FOREIGN KEY(user_id) REFERENCES app_users(id),FOREIGN KEY(event_id) REFERENCES events(id));
CREATE INDEX ix_booking_expiry ON bookings(status,expires_at);
CREATE TABLE event_seats (id BIGINT AUTO_INCREMENT PRIMARY KEY,event_id BIGINT NOT NULL,seat_id BIGINT NOT NULL,booking_id BIGINT,CONSTRAINT uq_event_seat UNIQUE(event_id,seat_id),FOREIGN KEY(event_id) REFERENCES events(id),FOREIGN KEY(seat_id) REFERENCES seats(id),FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE INDEX ix_inventory_booking ON event_seats(booking_id);
CREATE TABLE booking_items (id BIGINT AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT NOT NULL,event_seat_id BIGINT NOT NULL,price DECIMAL(19,2) NOT NULL,currency VARCHAR(3) NOT NULL,CONSTRAINT uq_booking_inventory UNIQUE(booking_id,event_seat_id),FOREIGN KEY(booking_id) REFERENCES bookings(id),FOREIGN KEY(event_seat_id) REFERENCES event_seats(id));
CREATE TABLE payment_attempts (id BIGINT AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT NOT NULL,idempotency_key VARCHAR(80) NOT NULL UNIQUE,outcome VARCHAR(20) NOT NULL,request_hash VARCHAR(64) NOT NULL,created_at TIMESTAMP(6) NOT NULL,FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE tickets (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,booking_item_id BIGINT NOT NULL UNIQUE,code VARCHAR(36) NOT NULL UNIQUE,issued_at TIMESTAMP(6) NOT NULL,FOREIGN KEY(user_id) REFERENCES app_users(id),FOREIGN KEY(booking_item_id) REFERENCES booking_items(id));
CREATE TABLE notification_outbox (id BIGINT AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT NOT NULL UNIQUE,recipient VARCHAR(254) NOT NULL,attempts INTEGER NOT NULL,delivered BOOLEAN NOT NULL,next_attempt_at TIMESTAMP(6) NOT NULL,FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE INDEX ix_outbox_due ON notification_outbox(delivered,next_attempt_at);
